class Writer {
  constructor(index) {
    this.index = index;
    this.pendingDocuments = [];
  }

  addDocument(document) {
    this.pendingDocuments.push({ ...document });
  }

  commit() {
    this.index.documents.push(...this.pendingDocuments);
    this.pendingDocuments = [];
  }
}

class Searcher {
  constructor(index) {
    this.index = index;
  }

  search(query) {
    return this.index.documents.filter((document) => query.matches(document));
  }
}

class InMemoryIndex {
  constructor(directory, schema) {
    this.directory = directory;
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new Writer(this);
  }

  searcher() {
    return new Searcher(this);
  }
}

export function createIn(directory, schema) {
  return new InMemoryIndex(directory, schema);
}

