const OPTION_NAMES = ['--a', '--b', '--c'];
const ATTACHED_VALUE_PATTERN = /^(--[a-z])=(.*)$/;
const NEGATIVE_NUMBER_PATTERN = /^-(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$/;

function isNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function isOptionLikeToken(token) {
  return token.startsWith('-') && !isNegativeNumberToken(token);
}

function writeAndExit(streamName, text, exitCode) {
  process[streamName].write(text);
  process.exit(exitCode);
}

function exitWithHelp(argv) {
  writeAndExit('stdout', formatHelpText(argv), 0);
}

function exitWithError(argv, text) {
  writeAndExit('stderr', text, 2);
}

export function parseCommandLine(argv = process.argv) {
  const values = { a: undefined, b: undefined, c: undefined };
  const extras = [];
  let parsingOptions = true;

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (parsingOptions && (token === '-h' || token === '--help')) {
      exitWithHelp(argv);
    }

    if (parsingOptions && token === '--') {
      parsingOptions = false;
      continue;
    }

    if (parsingOptions) {
      const attachedMatch = token.match(ATTACHED_VALUE_PATTERN);
      if (attachedMatch !== null && OPTION_NAMES.includes(attachedMatch[1])) {
        values[attachedMatch[1].slice(2)] = attachedMatch[2];
        continue;
      }

      if (OPTION_NAMES.includes(token)) {
        const nextToken = argv[index + 1];
        if (nextToken === undefined || isOptionLikeToken(nextToken)) {
          exitWithError(argv, formatExpectedArgumentError(argv, token));
        }

        values[token.slice(2)] = nextToken;
        index += 1;
        continue;
      }
    }

    extras.push(token);
  }

  const missingOptions = OPTION_NAMES.filter((optionName) => values[optionName.slice(2)] === undefined);
  if (missingOptions.length > 0) {
    exitWithError(argv, formatRequiredArgumentsError(argv, missingOptions));
  }

  if (extras.length > 0) {
    exitWithError(argv, formatUnrecognizedArgumentsError(argv, extras));
  }

  return values;
}

